THEME = ("T11", "Conformité, audit et gouvernance des accès")
SOURCE = "ISO/IEC 27001:2022 (annexe A 5.15, 5.16, 5.18, 8.2, 8.3, 8.15) ; Directive (UE) 2022/2555 NIS 2, art. 21 ; RGPD (UE) 2016/679, art. 5, 25, 32 ; ANSSI, Guide d'hygiène informatique ⚠ à vérifier"
Q = [
(1,"Quelle norme internationale décrit un système de management de la sécurité de l'information ?","ISO/IEC 27001","ISO 9001","ISO 14001","ISO 45001",
 "Elle exige des mesures de contrôle d'accès parmi d'autres."),
(2,"Quelle mesure de l'annexe A d'ISO/IEC 27001:2022 traite du contrôle d'accès ?","5.15","6.1","7.9","9.3",
 "La mesure 5.15 impose des règles de contrôle d'accès physique et logique fondées sur les exigences métier et de sécurité."),
(2,"Que traite la mesure 5.16 d'ISO/IEC 27001:2022 ?","La gestion des identités","La climatisation","La relation fournisseurs","La sauvegarde",
 "Elle couvre le cycle de vie complet des identités."),
(2,"Que traite la mesure 5.18 d'ISO/IEC 27001:2022 ?","Les droits d'accès (attribution, revue, retrait)","La destruction des supports","Le télétravail","Le plan de continuité",
 "Elle demande de contrôler l'octroi, la modification et le retrait des droits."),
(2,"Que traite la mesure 8.2 d'ISO/IEC 27001:2022 ?","Les droits d'accès privilégiés","Les sauvegardes","Le développement sécurisé","La cryptographie",
 "Les droits privilégiés doivent être restreints et gérés."),
(2,"Que traite la mesure 8.3 d'ISO/IEC 27001:2022 ?","La restriction d'accès à l'information","La journalisation","La gestion des actifs","La formation",
 "L'accès aux informations et aux applications est limité selon la politique."),
(2,"Que traite la mesure 8.15 d'ISO/IEC 27001:2022 ?","La journalisation","Le chiffrement","La gestion des incidents","La classification",
 "Les journaux doivent enregistrer, protéger et analyser les événements."),
(2,"Quel texte européen impose des mesures de gestion des risques cyber aux entités essentielles et importantes ?","La directive NIS 2","La directive vie privée et communications électroniques","Le règlement eIDAS seulement","La directive sur les poids et mesures",
 "L'article 21 liste les mesures, dont le contrôle d'accès et la gestion des actifs."),
(2,"Quelle mesure de l'article 21 de NIS 2 concerne spécifiquement les accès ?","La sécurité des ressources humaines, la politique de contrôle d'accès et la gestion des actifs","La politique de restauration","La gestion des couleurs","La politique des véhicules",
 "Elle figure parmi les mesures minimales exigées."),
(2,"Quel principe du RGPD impose de limiter l'accès aux seules personnes qui en ont besoin ?","L'intégrité et la confidentialité (art. 5) avec la sécurité du traitement (art. 32)","La portabilité","Le droit à l'oubli seulement","La minimisation des couleurs",
 "Les mesures de sécurité doivent assurer la confidentialité et contrôler les accès."),
(2,"Quel principe du RGPD demande de prévoir la protection dès la conception ?","Protection des données dès la conception et par défaut (art. 25)","Droit d'accès","Droit de rectification","Droit à la limitation",
 "Les accès aux données personnelles doivent être limités par défaut."),
(2,"Quelle obligation concerne la violation de données personnelles ?","Notification à l'autorité compétente dans les 72 heures lorsque c'est requis","Information au plus tard dans un an","Aucune notification","Suppression de la base",
 "Le RGPD (art. 33) impose une notification sous 72 heures en cas de risque."),
(1,"Quel contrôle prouve qu'une règle de droits est appliquée ?","Un audit des droits par échantillonnage ou complet","Un fond d'écran","Un changement de mot de passe","Une affiche",
 "L'audit compare les droits réels à la politique."),
(2,"Quelle différence entre un audit interne et un audit externe ?","L'audit interne est réalisé par l'organisation, l'externe par un tiers indépendant","Il n'y en a pas","L'interne est anonyme","L'externe est gratuit",
 "L'indépendance renforce la crédibilité."),
(2,"Quel est le rôle de la séparation des tâches en conformité ?","Réduire le risque de fraude et d'erreur non détectée","Augmenter la vitesse","Supprimer les contrôles","Chiffrer les données",
 "Elle est exigée par de nombreux référentiels financiers et de sécurité."),
(2,"Que signifie « traçabilité » dans un audit ?","Pouvoir reconstituer qui a fait quoi, quand et avec quels droits","Pouvoir supprimer les journaux","Pouvoir tout copier","Pouvoir tout partager",
 "Elle repose sur des identités individuelles et des journaux protégés."),
(2,"Quelle durée de conservation des journaux est requise par la loi en France pour tous les cas ?","Elle dépend du contexte réglementaire et de la finalité","Toujours dix ans","Toujours un jour","Aucune durée n'est jamais requise",
 "Il faut équilibrer les obligations légales et la minimisation des données personnelles."),
(2,"Que contient une matrice de séparation des tâches ?","Les combinaisons de droits ou rôles incompatibles","Les noms des visiteurs","Les adresses IP","Les numéros de série",
 "Elle sert de référence pour détecter des cumuls interdits."),
(3,"Quel écart est le plus grave lors d'un audit des droits ?","Un administrateur parti depuis six mois avec un compte actif","Un fond d'écran non conforme","Un nom de groupe long","Une signature de courriel différente",
 "Un compte actif d'ancien salarié est une exposition directe."),
(2,"Quel est l'objectif d'une revue annuelle des droits privilégiés ?","Vérifier que chaque privilège est justifié, tracé et approuvé","Augmenter les privilèges","Supprimer les journaux","Réduire la taille de l'annuaire",
 "Les privilèges élevés exigent une revue plus fréquente que les droits ordinaires."),
(2,"Quelle fréquence est généralement retenue pour les revues de droits privilégiés ?","Au moins trimestrielle ou semestrielle","Tous les dix ans","Jamais","Seulement après un incident",
 "Plus un droit est sensible, plus la revue est fréquente."),
(2,"Quelle preuve doit-on pouvoir fournir lors d'un audit d'accès ?","La demande, l'approbation et la date d'attribution de chaque droit sensible","Une photo de l'équipe","Le logo","Une facture d'électricité",
 "Cette preuve montre que le droit a été donné selon la procédure."),
(2,"Qu'est-ce qu'un risque résiduel ?","Le risque qui subsiste après application des mesures","Le risque nul","Un risque ancien","Un risque supprimé",
 "Il doit être accepté formellement par la direction."),
(2,"Qui accepte un risque résiduel d'accès ?","Le responsable désigné de l'actif ou la direction","Un technicien seul","Un visiteur","Le fournisseur",
 "L'acceptation est une décision de gouvernance, pas une décision technique."),
(2,"Qu'est-ce qu'une analyse d'impact sur la vie privée (AIPD) ?","Une évaluation des risques d'un traitement de données personnelles à risque élevé","Un audit financier","Un test de charge","Une sauvegarde",
 "Elle examine notamment les accès et les mesures de sécurité."),
(2,"Quelle action réduit le risque d'accès curieux aux dossiers de personnes connues dans une organisation ?","Journalisation des consultations et contrôle a posteriori","Aucun contrôle","Un accès libre pour tous","La suppression des journaux",
 "La dissuasion et la détection protègent les données personnelles."),
(3,"Quelle situation constitue une violation du principe de minimisation d'accès ?","Un service marketing accède aux dossiers médicaux de clients sans besoin","Un médecin lit le dossier de son patient","Un comptable lit les factures","Un magasinier lit les stocks",
 "L'accès doit être justifié par la finalité du traitement."),
(2,"Quel document décrit les responsabilités d'un administrateur de systèmes ?","Une charte d'administration signée","Un fond d'écran","Un menu de cantine","Un plan d'évacuation",
 "Elle rappelle les devoirs de confidentialité et de traçabilité."),
(2,"Quelle fonction indépendante contrôle l'application de la politique de sécurité ?","L'audit ou le contrôle interne","L'accueil","La maintenance du bâtiment","La comptabilité clients",
 "L'indépendance est nécessaire pour éviter qu'on se contrôle soi-même."),
(2,"Pourquoi former les utilisateurs au contrôle d'accès ?","Pour qu'ils comprennent leurs responsabilités et évitent le partage d'identifiants","Pour réduire les licences","Pour supprimer les journaux","Pour changer le logo",
 "Les erreurs humaines restent un facteur majeur d'incidents."),
(2,"Quel est l'effet d'une sanction clairement annoncée pour l'abus de droits ?","Un effet dissuasif complémentaire aux contrôles techniques","Aucun effet","Une panne","Une perte de données",
 "La charte informatique et le règlement intérieur encadrent ces sanctions."),
(3,"Quelle limite le droit du travail impose-t-il à la surveillance des accès des salariés ?","Information préalable et proportionnalité","Aucune limite","Interdiction totale de toute journalisation","Surveillance secrète autorisée",
 "Les dispositifs de contrôle doivent être connus des salariés et proportionnés au but."),
(2,"Quel indicateur de pilotage suit la qualité de la gestion des droits ?","Le taux de comptes orphelins ou de droits retirés à temps","Le nombre de fonds d'écran","Le poids du serveur","La taille du bureau",
 "Les indicateurs permettent de piloter et de rendre compte à la direction."),
(2,"Quel indicateur suit l'efficacité des revues de droits ?","Le pourcentage de droits retirés après revue","Le nombre de courriels","Le débit du réseau","La température",
 "Une revue qui ne retire jamais rien est suspecte."),
(3,"Une revue qui valide 100 % des droits sans en retirer aucun doit alerter parce que :","Les responsables ont probablement validé sans examiner","Les droits sont toujours parfaits","Elle est trop rapide","Elle est trop chère",
 "Le risque de validation automatique (« rubber stamping ») est connu."),
(2,"Comment limiter le « rubber stamping » ?","Fournir aux responsables des informations utiles (dernier usage, rôle) et des échantillons de contrôle","Supprimer la revue","Augmenter les droits","Masquer les données",
 "Une bonne revue aide à décider avec des éléments concrets."),
(2,"Quelle mesure répond à l'exigence NIS 2 de gestion des incidents liés aux accès ?","Détection, escalade et traitement des accès anormaux","Aucune mesure","L'oubli volontaire","La suppression du journal",
 "Elle s'appuie sur les journaux et la supervision."),
(2,"Que signifie le principe de « responsabilisation » (accountability) du RGPD ?","Pouvoir démontrer que l'on respecte les règles","Cacher les règles","Supprimer les données","Eviter tout contrôle",
 "Documentation, journaux et preuves sont indispensables."),
(2,"Quelle catégorie de données impose une protection renforcée des accès ?","Les données de santé et autres données sensibles","Les noms de produits","Les prix publics","Les horaires d'ouverture",
 "Les données sensibles exigent des mesures plus strictes."),
(3,"Quel est le risque d'accorder un accès « en lecture » à une base entière sans filtrage par finalité ?","Une consultation excessive de données personnelles sans justification","Aucun risque","Une panne réseau","Un excès de sauvegardes",
 "La minimisation s'applique aussi aux accès en lecture."),
(2,"Qu'est-ce qu'un registre des traitements ?","Un document qui décrit les traitements de données personnelles, leurs finalités et leurs destinataires","Un journal de connexions","Un plan de bâtiment","Une liste de fournisseurs",
 "Il aide à définir qui doit accéder à quelles données."),
(2,"Quelle mesure ANSSI de base concerne les accès ?","Identifier nommément chaque personne accédant au système et distinguer les comptes privilégiés","Utiliser un compte partagé","Désactiver les journaux","Autoriser les accès anonymes",
 "Le guide d'hygiène demande des comptes nominatifs et la limitation des droits d'administration."),
(2,"Pourquoi faut-il limiter le nombre d'administrateurs ?","Chaque compte à privilèges élargit la surface d'attaque","Pour réduire les licences uniquement","Pour accélérer le réseau","Pour supprimer les rôles",
 "Moins de comptes privilégiés, c'est moins de cibles et moins de risques d'erreur."),
(1,"Quelle fonction a une charte informatique ?","Fixer les règles d'usage du système d'information et les responsabilités","Choisir le logo","Remplacer les mots de passe","Remplacer l'audit",
 "Elle est annexée au règlement intérieur pour être opposable."),
]
